export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-20\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 20,\n    \"title\": \"難三\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 13,\n    \"passageIds\": [\n      \"han-fei-zi_ch-20_p-1\",\n      \"han-fei-zi_ch-20_p-2\",\n      \"han-fei-zi_ch-20_p-3\",\n      \"han-fei-zi_ch-20_p-4\",\n      \"han-fei-zi_ch-20_p-5\",\n      \"han-fei-zi_ch-20_p-6\",\n      \"han-fei-zi_ch-20_p-7\",\n      \"han-fei-zi_ch-20_p-8\",\n      \"han-fei-zi_ch-20_p-9\",\n      \"han-fei-zi_ch-20_p-10\",\n      \"han-fei-zi_ch-20_p-11\",\n      \"han-fei-zi_ch-20_p-12\",\n      \"han-fei-zi_ch-20_p-13\",\n      \"han-fei-zi_ch-20_p-14\",\n      \"han-fei-zi_ch-20_p-15\",\n      \"han-fei-zi_ch-20_p-16\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-20_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 1,\n      \"canonicalText\": \"魯穆公問於子思曰：「吾聞龐𥼴氏之子不孝，其行奚如？」子思對曰：「君子尊賢以崇德，舉善以觀民。若夫過行，是細人之所識也，臣不知也。」子思出，子服厲伯入見，問龐𥼴氏子，子服厲伯對曰：「其過三，皆君之所未嘗聞。」自是之後，君貴子思而賤子服厲伯也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-1_s-1\",\n        \"han-fei-zi_ch-20_p-1_s-2\",\n        \"han-fei-zi_ch-20_p-1_s-3\",\n        \"han-fei-zi_ch-20_p-1_s-4\",\n        \"han-fei-zi_ch-20_p-1_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"魯穆公問於子思說道：吾聞龐𥼴氏的子不孝，他的行奚如？子思對說道：國君子尊賢以崇德，舉善以觀民。至於談到那過行，是細人的所識啊，臣屬不知啊。子思出，子服厲伯入見，問龐𥼴氏子，子服厲伯對說道：他的過三，皆國君的所未嘗聞。自是的後，國君貴子思而且賤子服厲伯啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「魯穆公問於子思曰：「吾聞龐𥼴氏之子不孝，其行奚如」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「魯」、「穆」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「魯穆公問於子思曰吾聞龐𥼴氏之子不孝其行奚如子思」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」子思對曰：「君子尊賢以崇德，舉善以觀民」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 2,\n      \"canonicalText\": \"或曰：魯之公室，三世劫於季氏，不亦宜乎！明君求善而賞之，求姦而誅之，其得之一也。故以善聞之者，以說善同於上者也；以姦聞之者，以惡姦同於上者也；此宜賞譽之所力也。不以姦聞，是異於上而下比周於姦者也，此宜毀罰之所及也。今子思不以過聞，而穆公貴之，厲伯以姦聞而穆公賤之，人情皆喜貴而惡賤，故季氏之亂成而不上聞，此魯君之所以劫也。且此亡王之俗，取、魯之民所以自美，而穆公獨貴之，不亦倒乎！\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-2_s-1\",\n        \"han-fei-zi_ch-20_p-2_s-2\",\n        \"han-fei-zi_ch-20_p-2_s-3\",\n        \"han-fei-zi_ch-20_p-2_s-4\",\n        \"han-fei-zi_ch-20_p-2_s-5\",\n        \"han-fei-zi_ch-20_p-2_s-6\",\n        \"han-fei-zi_ch-20_p-2_s-7\",\n        \"han-fei-zi_ch-20_p-2_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：魯的公室，三世劫於季氏，不亦宜乎！明國君求善而且賞賜的，求姦而且誅的，他的得的一啊。所以以善聞的的人或事，以說善同於上的人或事啊；以姦聞的的人或事，以惡姦同於上的人或事啊；此宜賞賜譽的所力啊。不以姦聞，是異於上而且下比周於姦的人或事啊，此宜毀刑罰的所及啊。今子思不以過聞，而且穆公貴的，厲伯以姦聞而且穆公賤的，人情皆喜貴而且惡賤，所以季氏的亂成而且不上聞，此魯國君的所以劫啊。且此亡王的俗，取、魯的民所以自美，而且穆公獨貴的，不亦倒乎！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：魯之公室，三世劫於季氏，不亦宜乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「魯」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰魯之公室三世劫於季氏不亦宜乎明君求善而賞之求」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「明君求善而賞之，求姦而誅之，其得之一也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 3,\n      \"canonicalText\": \"文公出亡，獻公使寺人披攻之蒲城，披斬其袪，文公奔翟。惠公即位，又使攻之惠竇，不得也。及文公反國，披求見。公曰：「蒲城之役，君令一宿，而汝即至；惠竇之難，君令三宿，而汝一宿，何其速也？」披對曰：「君令不二，除君之惡，惟恐不堪，蒲人、翟人餘何有焉？今公即位，其無蒲、翟乎！且桓公置射鉤而相管仲。」君乃見之。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-3_s-1\",\n        \"han-fei-zi_ch-20_p-3_s-2\",\n        \"han-fei-zi_ch-20_p-3_s-3\",\n        \"han-fei-zi_ch-20_p-3_s-4\",\n        \"han-fei-zi_ch-20_p-3_s-5\",\n        \"han-fei-zi_ch-20_p-3_s-6\",\n        \"han-fei-zi_ch-20_p-3_s-7\",\n        \"han-fei-zi_ch-20_p-3_s-8\",\n        \"han-fei-zi_ch-20_p-3_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"文公出亡，獻公使寺人披攻的蒲城，披斬他的袪，文公奔翟。惠公即位，又使攻的惠竇，不得啊。及文公反國，披求見。公說道：蒲城的役，君主統治者令一宿，而且汝即至；惠竇的難，君主統治者令三宿，而且汝一宿，何他的速啊？披對說道：君主統治者令不二，除君主統治者的惡，惟恐不堪，蒲人、翟人餘何有焉？今公即位，他的無蒲、翟乎！且桓公置射鉤而且相管仲。君主統治者乃見的。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「文公出亡，獻公使寺人披攻之蒲城，披斬其袪，文公奔翟」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「文」、「公」、「出」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「文公出亡獻公使寺人披攻之蒲城披斬其袪文公奔翟惠公」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「惠公即位，又使攻之惠竇，不得也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 4,\n      \"canonicalText\": \"或曰：齊、晉絕祀，不亦宜乎！桓公能用管仲之功而忘射鉤之怨，文公能聽寺人之言而棄斬袪之罪，桓公、文公能容二子者也。後世之君，明不及二公；後世之臣，賢不如二子。以不忠之臣事不明之君。君不知，則有燕操、子罕、田常之賊；知之，則以管仲、寺人自解。君必不誅，而自以為有桓、文之德，是臣讎而明不能燭，多假之資。自以為賢而不戒，則雖無後嗣，不亦可乎！且寺人之言也，直飾君令而不貳者，則是貞於君也。死君後生臣不愧而復為貞，今惠公朝卒而暮事文公，寺人之不貳何如？\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-4_s-1\",\n        \"han-fei-zi_ch-20_p-4_s-2\",\n        \"han-fei-zi_ch-20_p-4_s-3\",\n        \"han-fei-zi_ch-20_p-4_s-4\",\n        \"han-fei-zi_ch-20_p-4_s-5\",\n        \"han-fei-zi_ch-20_p-4_s-6\",\n        \"han-fei-zi_ch-20_p-4_s-7\",\n        \"han-fei-zi_ch-20_p-4_s-8\",\n        \"han-fei-zi_ch-20_p-4_s-9\",\n        \"han-fei-zi_ch-20_p-4_s-10\",\n        \"han-fei-zi_ch-20_p-4_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：齊、晉絕祀，不亦宜乎！桓公能用管仲的功而且忘射鉤的怨，文公能聽寺人的言而且棄斬袪的罪，桓公、文公能容二子的人或事啊。後世的國君，明不及二公；後世的臣屬，賢不如二子。以不忠的臣屬事不明的國君。國君不知，則有燕操、子罕、田常的賊；知的，則以管仲、寺人自解。國君必不誅，而且自以為有桓、文的德，是臣屬讎而且明不能燭，多假的資。自以為賢而且不戒，則雖無後嗣，不亦可乎！且寺人的言啊，直飾國君令而且不貳的人或事，則是貞於國君啊。死國君後生臣屬不愧而且復為貞，今惠公朝卒而且暮事文公，寺人的不貳何如？\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：齊、晉絕祀，不亦宜乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「齊」、「晉」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰齊晉絕祀不亦宜乎桓公能用管仲之功而忘射鉤之怨」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「桓公能用管仲之功而忘射鉤之怨，文公能聽寺人之言而棄斬袪之罪，桓公、文公能容二子者也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 5,\n      \"canonicalText\": \"人有設桓公隱者曰：「一難，二難，三難，何也？」桓公不能對，以告管仲。管仲對曰：「一難也、近優而遠士。二難也、去其國而數之海。三難也、君老而晚置太子。」桓公曰：「善。」不擇日而廟禮太子。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-5_s-1\",\n        \"han-fei-zi_ch-20_p-5_s-2\",\n        \"han-fei-zi_ch-20_p-5_s-3\",\n        \"han-fei-zi_ch-20_p-5_s-4\",\n        \"han-fei-zi_ch-20_p-5_s-5\",\n        \"han-fei-zi_ch-20_p-5_s-6\",\n        \"han-fei-zi_ch-20_p-5_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"人有設桓公隱的人或事說道：一難，二難，三難，何啊？桓公不能對，以告管仲。管仲對說道：一難啊、近優而且遠士。二難啊、去他的國而且數的海。三難啊、國君老而且晚置太子。桓公說道：善。不擇日而且廟禮太子。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「人有設桓公隱者曰：「一難，二難，三難，何也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「人」、「有」、「設」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「人有設桓公隱者曰一難二難三難何也桓公不能對以告管」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」桓公不能對，以告管仲」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 6,\n      \"canonicalText\": \"或曰：管仲之射隱不得也。士之用不在近遠。而俳優侏儒，固人主之所與燕也。則近優而遠士，而以為治，非其難者也。夫處勢而不能用其有，而悖不去國，是以一人之力禁一國。以一人之力禁一國者，少能勝之。明能照遠姦而見隱微，必行之令，雖遠於海，內必無變；然則去國之海而不劫殺，非其難者也。楚成王置商臣以為太子，又欲置公子職，商臣作難，遂弒成王。公子宰，周太子也，公子根有寵，遂以東州反，分而為兩國。此皆非晚置太子之患也。夫分勢不二，庶孽卑，寵無藉，雖處大臣，晚置太子可也；然則晚置太子，庶孽不亂，又非其難也。物之所謂難者；必借人成勢而勿使侵害己，可謂一難也。貴妾不使二後，二難也。愛孽不使危正適，專聽一臣而不敢隅君，此則可謂三難也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-6_s-1\",\n        \"han-fei-zi_ch-20_p-6_s-2\",\n        \"han-fei-zi_ch-20_p-6_s-3\",\n        \"han-fei-zi_ch-20_p-6_s-4\",\n        \"han-fei-zi_ch-20_p-6_s-5\",\n        \"han-fei-zi_ch-20_p-6_s-6\",\n        \"han-fei-zi_ch-20_p-6_s-7\",\n        \"han-fei-zi_ch-20_p-6_s-8\",\n        \"han-fei-zi_ch-20_p-6_s-9\",\n        \"han-fei-zi_ch-20_p-6_s-10\",\n        \"han-fei-zi_ch-20_p-6_s-11\",\n        \"han-fei-zi_ch-20_p-6_s-12\",\n        \"han-fei-zi_ch-20_p-6_s-13\",\n        \"han-fei-zi_ch-20_p-6_s-14\",\n        \"han-fei-zi_ch-20_p-6_s-15\",\n        \"han-fei-zi_ch-20_p-6_s-16\",\n        \"han-fei-zi_ch-20_p-6_s-17\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：管仲的射隱不得啊。士的用不在近遠。而且俳優侏儒，固人主的所與燕啊。則近優而且遠士，而且以為治，絕不是他的難的人或事啊。夫處權位威勢而且不能用他的有，而且悖不去國，是以一人的力禁一國。以一人的力禁一國的人或事，少能勝的。明能照遠姦而且見隱微，必行的令，雖遠於海，內必無變；然則去國的海而且不劫殺，絕不是他的難的人或事啊。楚成王置商臣屬以為太子，又欲置公子職，商臣屬作難，遂弒成王。公子宰，周太子啊，公子根有寵，遂以東州反，分而且為兩國。此皆絕不是晚置太子的患啊。夫分權位威勢不二，庶孽卑，寵無藉，雖處大臣屬，晚置太子可啊；然則晚置太子，庶孽不亂，又絕不是他的難啊。物的所謂難的人或事；必借人成權位威勢而且勿使侵害己，可謂一難啊。貴妾不使二後，二難啊。愛孽不使危正適，專聽一臣屬而且不敢隅國君，此則可謂三難啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：管仲之射隱不得也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「管」、「仲」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰管仲之射隱不得也士之用不在近遠而俳優侏儒固人」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「士之用不在近遠」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 7,\n      \"canonicalText\": \"葉公子高問政於仲尼，仲尼曰：「政在悅近而來遠。」哀公問政於仲尼，仲尼曰：「政在選賢。」齊景公問政於仲尼，仲尼曰：「政在節財。」三公出，子貢問曰：「三公問夫子政一也，夫子對之不同，何也？」仲尼曰：「葉都大而國小，民有背心，故曰政在悅近而來遠。魯哀公有大臣三人，外障距諸侯四鄰之士，內比周而以愚其君，使宗廟不掃除，社稷不血食者，必是三臣也，故曰政在選賢。齊景公築雍門，為路寢，一朝而以三百乘之家賜者三，故曰政在節財。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-7_s-1\",\n        \"han-fei-zi_ch-20_p-7_s-2\",\n        \"han-fei-zi_ch-20_p-7_s-3\",\n        \"han-fei-zi_ch-20_p-7_s-4\",\n        \"han-fei-zi_ch-20_p-7_s-5\",\n        \"han-fei-zi_ch-20_p-7_s-6\",\n        \"han-fei-zi_ch-20_p-7_s-7\",\n        \"han-fei-zi_ch-20_p-7_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"葉公子高問政於仲尼，仲尼說道：政在悅近而且來遠。哀公問政於仲尼，仲尼說道：政在選賢。齊景公問政於仲尼，仲尼說道：政在節財。三公出，子貢問說道：三公問夫子政一啊，夫子對的不同，何啊？仲尼說道：葉都大而且國小，民有背心，因此韓絕不是子評論說道：政在悅近而且來遠。魯哀公有大臣屬三人，外障距諸侯四鄰的士，內比周而且以愚他的國君，使宗廟不掃除，社稷不血食的人或事，必是三臣屬啊，因此韓絕不是子評論說道：政在選賢。齊景公築雍門，為路寢，一朝而且以三百乘的家賜的人或事三，因此韓絕不是子評論說道：政在節財。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「葉公子高問政於仲尼，仲尼曰：「政在悅近而來遠」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「葉」、「公」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「葉公子高問政於仲尼仲尼曰政在悅近而來遠哀公問政於」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」哀公問政於仲尼，仲尼曰：「政在選賢」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 8,\n      \"canonicalText\": \"或曰：仲尼之對，亡國之言也。葉民有倍心，而說之悅近而來遠，則是教民懷惠。惠之為政，無功者受賞，而有罪者免，此法之所以敗也。法敗而政亂，以亂政治敗民，未見其可也。且民有倍心者，君上之明有所不及也。不紹葉公之明，而使之悅近而來遠，是舍吾勢之所能禁而使與不行惠以爭民，非能持勢者也。夫堯之賢，六王之冠也，舜一從而鹹包，而堯無天下矣。有人無術以禁下，恃為舜而不失其民，不亦無術乎！明君見小姦於微，故民無大謀；行小誅於細，故民無大亂；此謂圖難於其所易也，為大者於其所細也。今有功者必賞，賞者不得君，力之所致也；有罪者必誅，誅者不怨上，罪之所生也。民知誅罰之皆起於身也，故疾功利於業，而不受賜於君。「太上、下智有之。」此言太上之下民無說也，安取懷惠之民？上君之民無利害，說以悅近來遠，亦可捨己。哀公有臣外障距內比周以愚其君，而說之以選賢，此非功伐之論也，選其心之所謂賢者也。使哀公知三子外障距內比周也，則三子不一日立矣。哀公不知選賢，選其心之所謂賢，故三子得任事。燕子噲賢子之而非孫卿，故身死為僇。夫差智太宰嚭而愚子胥，故滅於越。魯君不必知賢，而說以選賢，是使哀公有夫差、燕噲之患也。明君不自舉臣，臣相進也；不自賢，功自徇也。論之於任，試之於事，課之於功。故群臣公政而無私，不隱賢，不進不肖，然則人主奚勞於選賢？景公以百乘之家賜，而說以節財，是使景公無術使智君之侈，而獨儉於上，未免於貧也。有君以千里養其口腹，則雖桀、紂不侈焉。齊國方三千里，而桓公以其半自養，是侈於桀、紂也，然而能為五霸冠者，知侈儉之地也。為君不能禁下而自禁者謂之劫，不能飾下而自飾者謂之亂，不節下而自節者謂之貧。明君使人無私，以詐而食者禁；力盡於事，歸利於上者必聞，聞者必賞；污穢為私者必知，知者必誅。然故忠臣盡忠於方公，民士竭力於家，百官精剋於上，侈倍景公，非國之患也。然則說之以節財，非其急者也。夫對三公一言而三公可以無患，知下之謂也。知下明則禁於微，禁於微則姦無積，姦無積則無比周。無比周則公私分，公私分則朋黨散，朋黨散則無外障距內比周之患。知下明則見精沐，見精沐則誅賞明，誅賞明則國不貧，故曰一對而三公無患，知下之謂也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-8_s-1\",\n        \"han-fei-zi_ch-20_p-8_s-2\",\n        \"han-fei-zi_ch-20_p-8_s-3\",\n        \"han-fei-zi_ch-20_p-8_s-4\",\n        \"han-fei-zi_ch-20_p-8_s-5\",\n        \"han-fei-zi_ch-20_p-8_s-6\",\n        \"han-fei-zi_ch-20_p-8_s-7\",\n        \"han-fei-zi_ch-20_p-8_s-8\",\n        \"han-fei-zi_ch-20_p-8_s-9\",\n        \"han-fei-zi_ch-20_p-8_s-10\",\n        \"han-fei-zi_ch-20_p-8_s-11\",\n        \"han-fei-zi_ch-20_p-8_s-12\",\n        \"han-fei-zi_ch-20_p-8_s-13\",\n        \"han-fei-zi_ch-20_p-8_s-14\",\n        \"han-fei-zi_ch-20_p-8_s-15\",\n        \"han-fei-zi_ch-20_p-8_s-16\",\n        \"han-fei-zi_ch-20_p-8_s-17\",\n        \"han-fei-zi_ch-20_p-8_s-18\",\n        \"han-fei-zi_ch-20_p-8_s-19\",\n        \"han-fei-zi_ch-20_p-8_s-20\",\n        \"han-fei-zi_ch-20_p-8_s-21\",\n        \"han-fei-zi_ch-20_p-8_s-22\",\n        \"han-fei-zi_ch-20_p-8_s-23\",\n        \"han-fei-zi_ch-20_p-8_s-24\",\n        \"han-fei-zi_ch-20_p-8_s-25\",\n        \"han-fei-zi_ch-20_p-8_s-26\",\n        \"han-fei-zi_ch-20_p-8_s-27\",\n        \"han-fei-zi_ch-20_p-8_s-28\",\n        \"han-fei-zi_ch-20_p-8_s-29\",\n        \"han-fei-zi_ch-20_p-8_s-30\",\n        \"han-fei-zi_ch-20_p-8_s-31\",\n        \"han-fei-zi_ch-20_p-8_s-32\",\n        \"han-fei-zi_ch-20_p-8_s-33\",\n        \"han-fei-zi_ch-20_p-8_s-34\",\n        \"han-fei-zi_ch-20_p-8_s-35\",\n        \"han-fei-zi_ch-20_p-8_s-36\",\n        \"han-fei-zi_ch-20_p-8_s-37\",\n        \"han-fei-zi_ch-20_p-8_s-38\",\n        \"han-fei-zi_ch-20_p-8_s-39\",\n        \"han-fei-zi_ch-20_p-8_s-40\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：仲尼的對，亡國的言啊。葉民有倍心，而且說的悅近而且來遠，則是教民懷惠。惠的為政，無功的人或事受賞賜，而且有罪的人或事免，此法規法令的所以敗啊。法規法令敗而且政亂，以亂政治敗民，未見他的可啊。且民有倍心的人或事，國君上的明有所不及啊。不紹葉公的明，而且使的悅近而且來遠，是舍吾權位威勢的所能禁而且使與不行惠以爭民，絕不是能持權位威勢的人或事啊。夫堯的賢，六王的冠啊，舜一從而且鹹包，而且堯無天下矣。有人無督察權術以禁下，恃為舜而且不失他的民，不亦無督察權術乎！明國君見小姦於微，所以民無大謀；行小誅於細，所以民無大亂；此謂圖難於他的所易啊，為大的人或事於他的所細啊。今有功的人或事必賞賜，賞賜的人或事不得國君，力的所致啊；有罪的人或事必誅，誅的人或事不怨上，罪的所生啊。民知誅刑罰的皆起於身啊，所以疾功利於業，而且不受賜於國君。太上、下智有的。此言太上的下民無說啊，安取懷惠的民？上國君的民無利害，說以悅近來遠，亦可捨己。哀公有臣屬外障距內比周以愚他的國君，而且說的以選賢，此絕不是功伐的論啊，選他的心的所謂賢的人或事啊。使哀公知三子外障距內比周啊，則三子不一日立矣。哀公不知選賢，選他的心的所謂賢，所以三子得任事。燕子噲賢子的而且絕不是孫卿，所以身死為僇。夫差智太宰嚭而且愚子胥，所以滅於越。魯國君不必知賢，而且說以選賢，是使哀公有夫差、燕噲的患啊。明國君不自舉臣屬，臣屬相進啊；不自賢，功自徇啊。論的於任，試的於事，課的於功。所以群臣屬公政而且無私，不隱賢，不進不肖，然則人主奚勞於選賢？景公以百乘的家賜，而且說以節財，是使景公無督察權術使智國君的侈，而且獨儉於上，未免於貧啊。有國君以千里養他的口腹，則雖桀、紂不侈焉。齊國方三千里，而且桓公以他的半自養，是侈於桀、紂啊，然而且能為五霸冠的人或事，知侈儉的地啊。為國君不能禁下而且自禁的人或事謂的劫，不能飾下而且自飾的人或事謂的亂，不節下而且自節的人或事謂的貧。明國君使人無私，以詐而且食的人或事禁；力盡於事，歸利於上的人或事必聞，聞的人或事必賞賜；污穢為私的人或事必知，知的人或事必誅。然所以忠臣屬盡忠於方公，民士竭力於家，百官精剋於上，侈倍景公，絕不是國的患啊。然則說的以節財，絕不是他的急的人或事啊。夫對三公一言而且三公可以無患，知下的謂啊。知下明則禁於微，禁於微則姦無積，姦無積則無比周。無比周則公私分，公私分則朋黨散，朋黨散則無外障距內比周的患。知下明則見精沐，見精沐則誅賞賜明，誅賞賜明則國不貧，因此韓絕不是子評論說道：一對而且三公無患，知下的謂啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：仲尼之對，亡國之言也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「仲」、「尼」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰仲尼之對亡國之言也葉民有倍心而說之悅近而來遠」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「葉民有倍心，而說之悅近而來遠，則是教民懷惠」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 9,\n      \"canonicalText\": \"鄭子產晨出，過東匠之閭，聞婦人之哭，撫其御之手而聽之。有閒，遣吏執而問之，則手絞其夫者也。異日，其御問曰：「夫子何以知之？」子產曰：「其聲懼。凡人於其親愛也，始病而憂，臨死而懼，已死而哀。今哭已死不哀而懼，是以知其有姦也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-9_s-1\",\n        \"han-fei-zi_ch-20_p-9_s-2\",\n        \"han-fei-zi_ch-20_p-9_s-3\",\n        \"han-fei-zi_ch-20_p-9_s-4\",\n        \"han-fei-zi_ch-20_p-9_s-5\",\n        \"han-fei-zi_ch-20_p-9_s-6\",\n        \"han-fei-zi_ch-20_p-9_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"鄭子產晨出，過東匠的閭，聞婦人的哭，撫他的御的手而且聽的。有閒，遣吏執而且問的，則手絞他的夫的人或事啊。異日，他的御問說道：夫子何以知的？子產說道：他的聲懼。凡人於他的親愛啊，始病而且憂，臨死而且懼，已死而且哀。今哭已死不哀而且懼，是以知他的有姦啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「鄭子產晨出，過東匠之閭，聞婦人之哭，撫其御之手而聽之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「鄭」、「子」、「產」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「鄭子產晨出過東匠之閭聞婦人之哭撫其御之手而聽之有」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「有閒，遣吏執而問之，則手絞其夫者也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 10,\n      \"canonicalText\": \"或曰：子產之治，不亦多事乎？姦必待耳目之所及而後知之，則鄭國之得姦者寡矣。不任典成之吏，不察參伍之政，不明度量，恃盡聰明，勞智慮，而以知姦，不亦無術乎？且夫物眾而智寡，寡不勝眾，智不足以遍知物，故因物以治物。下眾而上寡，寡不勝眾，者言君不足以遍知臣也，故因人以知人。是以形體不勞而事治，智慮不用而姦得。故宋人語曰：「一雀過羿，羿必得之，則羿誣矣。以天下為之羅，則雀不失矣。」夫知姦亦有大羅，不失其一而已矣。不修其理，而以己之胸察為之弓矢，則子產誣矣。老子曰：「以智治國，國之賊也。」其子產之謂矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-10_s-1\",\n        \"han-fei-zi_ch-20_p-10_s-2\",\n        \"han-fei-zi_ch-20_p-10_s-3\",\n        \"han-fei-zi_ch-20_p-10_s-4\",\n        \"han-fei-zi_ch-20_p-10_s-5\",\n        \"han-fei-zi_ch-20_p-10_s-6\",\n        \"han-fei-zi_ch-20_p-10_s-7\",\n        \"han-fei-zi_ch-20_p-10_s-8\",\n        \"han-fei-zi_ch-20_p-10_s-9\",\n        \"han-fei-zi_ch-20_p-10_s-10\",\n        \"han-fei-zi_ch-20_p-10_s-11\",\n        \"han-fei-zi_ch-20_p-10_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：子產的治，不亦多事乎？姦必待耳目的所及而且後知的，則鄭國的得姦的人或事寡矣。不任典成的吏，不察參伍的政，不明度量，恃盡聰明，勞智慮，而且以知姦，不亦無督察權術乎？再的人或事況且物眾而且智寡，寡不勝眾，智不足以遍知物，所以因物以治物。下眾而且上寡，寡不勝眾，的人或事言國君不足以遍知臣屬啊，所以因人以知人。是以形體不勞而且事治，智慮不用而且姦得。所以宋人語說道：一雀過羿，羿必得的，則羿誣矣。以天下為的羅，則雀不失矣。夫知姦亦有大羅，不失他的一而且已矣。不修他的理，而且以己的胸察為的弓矢，則子產誣矣。老子說道：以智治國，國的賊啊。他的子產的謂矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：子產之治，不亦多事乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「子」、「產」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰子產之治不亦多事乎姦必待耳目之所及而後知之則」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「姦必待耳目之所及而後知之，則鄭國之得姦者寡矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 11,\n      \"canonicalText\": \"秦昭王問於左右曰：「今時韓、魏孰與始強？」左右對曰：「弱於始也。」「今之如耳、魏齊孰與曩之孟常、芒卯？」對曰：「不及也。」王曰：「孟常、芒卯率強韓、魏猶無奈寡人何也！」左右對曰：「甚然！」中期推琴而對曰：「王之料天下過矣！夫六晉之時，知氏最強，滅範、中行而從韓、魏之兵以伐趙，灌以晉水，城之未沈者三板。知伯出，魏宣子御，韓康子為驂乘，知伯曰：「始吾不知水可以滅人之國，吾乃今知之。汾水可以灌安邑，絳水可以灌平陽。」魏宣子肘韓康子，康子踐宣子之足，肘足接乎車上，而知氏分於晉陽之下。今足下雖強，未若知氏；韓、魏雖弱，未至如其在晉陽之下也。此天下方用肘足之時，願王勿易之也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-11_s-1\",\n        \"han-fei-zi_ch-20_p-11_s-2\",\n        \"han-fei-zi_ch-20_p-11_s-3\",\n        \"han-fei-zi_ch-20_p-11_s-4\",\n        \"han-fei-zi_ch-20_p-11_s-5\",\n        \"han-fei-zi_ch-20_p-11_s-6\",\n        \"han-fei-zi_ch-20_p-11_s-7\",\n        \"han-fei-zi_ch-20_p-11_s-8\",\n        \"han-fei-zi_ch-20_p-11_s-9\",\n        \"han-fei-zi_ch-20_p-11_s-10\",\n        \"han-fei-zi_ch-20_p-11_s-11\",\n        \"han-fei-zi_ch-20_p-11_s-12\",\n        \"han-fei-zi_ch-20_p-11_s-13\",\n        \"han-fei-zi_ch-20_p-11_s-14\",\n        \"han-fei-zi_ch-20_p-11_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"秦昭王問於左右說道：今時韓、魏孰與始強？左右對說道：弱於始啊。今的如耳、魏齊孰與曩的孟常、芒卯？對說道：不及啊。王說道：孟常、芒卯率強韓、魏猶無奈寡人何啊！左右對說道：甚然！中期推琴而且對說道：王的料天下過矣！夫六晉的時，知氏最強，滅範、中行而且從韓、魏的兵以伐趙，灌以晉水，城的未沈的人或事三板。知伯出，魏宣子御，韓康子為驂乘，知伯說道：始吾不知水可以滅人的國，吾乃今知的。汾水可以灌安邑，絳水可以灌平陽。魏宣子肘韓康子，康子踐宣子的足，肘足接乎車上，而且知氏分於晉陽的下。今足下雖強，未若知氏；韓、魏雖弱，未至如他的在晉陽的下啊。此天下方用肘足的時，願王勿易的啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「秦昭王問於左右曰：「今時韓、魏孰與始強」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「秦」、「昭」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「秦昭王問於左右曰今時韓魏孰與始強左右對曰弱於始也」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」左右對曰：「弱於始也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 12,\n      \"canonicalText\": \"或曰：昭王之問也有失，左右中期之對也有過。凡明主之治國也，任其勢。勢不可害，則雖強天下無奈何也，而況孟常、芒卯、韓、魏能奈我何！其勢可害也，則不肖如如耳、魏齊，及韓、魏猶能害之。然則害與不侵，在自恃而已矣，奚問乎？自恃其不可侵，則強與弱奚其擇焉？失在不自恃，而問其奈何也，其不侵也幸矣！《申子》曰：「失之數而求之信則疑矣，」其昭王之謂也。知伯無度，從韓康、魏宣而圖以水灌滅其國，此知伯之所以國亡而身死、頭為飲杯之故也。今昭王乃問孰與始強，其畏有水人之患乎？雖有左右非韓、魏之二子也，安有肘足之事，而中期曰「勿易」，此虛言也。且中期之所官、琴瑟也，絃不調，弄不明，中期之任也，此中期所以事昭王者也。中期善承其任，未慊昭王也，而為所不知，豈不妄哉！左右對之曰「弱於始」與「不及」則可矣，其曰「甚然」則諛也。《申子》曰：「治不踰官，雖知不言。」今中期不知而尚言之。故曰昭王之問有失，左右中期之對皆有過也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-12_s-1\",\n        \"han-fei-zi_ch-20_p-12_s-2\",\n        \"han-fei-zi_ch-20_p-12_s-3\",\n        \"han-fei-zi_ch-20_p-12_s-4\",\n        \"han-fei-zi_ch-20_p-12_s-5\",\n        \"han-fei-zi_ch-20_p-12_s-6\",\n        \"han-fei-zi_ch-20_p-12_s-7\",\n        \"han-fei-zi_ch-20_p-12_s-8\",\n        \"han-fei-zi_ch-20_p-12_s-9\",\n        \"han-fei-zi_ch-20_p-12_s-10\",\n        \"han-fei-zi_ch-20_p-12_s-11\",\n        \"han-fei-zi_ch-20_p-12_s-12\",\n        \"han-fei-zi_ch-20_p-12_s-13\",\n        \"han-fei-zi_ch-20_p-12_s-14\",\n        \"han-fei-zi_ch-20_p-12_s-15\",\n        \"han-fei-zi_ch-20_p-12_s-16\",\n        \"han-fei-zi_ch-20_p-12_s-17\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：昭王的問啊有失，左右中期的對啊有過。凡明主的治國啊，任他的權位威勢。權位威勢不可害，則雖強天下無奈何啊，而且況孟常、芒卯、韓、魏能奈我何！他的權位威勢可害啊，則不肖如如耳、魏齊，及韓、魏猶能害的。然則害與不侵，在自恃而且已矣，奚問乎？自恃他的不可侵，則強與弱奚他的擇焉？失在不自恃，而且問他的奈何啊，他的不侵啊幸矣！《申子》說道：失的數而且求的信則疑矣，他的昭王的謂啊。知伯無度，從韓康、魏宣而且圖以水灌滅他的國，此知伯的所以國亡而且身死、頭為飲杯的所以啊。今昭王乃問孰與始強，他的畏有水人的患乎？雖有左右絕不是韓、魏的二子啊，安有肘足的事，而且中期說道：勿易，此虛言啊。且中期的所官、琴瑟啊，絃不調，弄不明，中期的任啊，此中期所以事昭王的人或事啊。中期善承他的任，未慊昭王啊，而且為所不知，豈不妄哉！左右對的說道：弱於始與不及則可矣，他的說道：甚然則諛啊。《申子》說道：治不踰官，雖知不言。今中期不知而且尚言的。因此韓絕不是子評論說道：昭王的問有失，左右中期的對皆有過啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：昭王之問也有失，左右中期之對也有過」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「昭」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰昭王之問也有失左右中期之對也有過凡明主之治國」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「凡明主之治國也，任其勢」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-13\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 13,\n      \"canonicalText\": \"管子曰：「見其可說之有證，見其不可惡之有形，賞罰信於所見，雖所不見，其敢為之乎？見其可說之無證，見其不可惡之無形，賞罰不信於所見，而求所不見之外，不可得也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-13_s-1\",\n        \"han-fei-zi_ch-20_p-13_s-2\",\n        \"han-fei-zi_ch-20_p-13_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"管子說道：見他的可說的有證，見他的不可惡的有形，賞賜與刑罰信於所見，雖所不見，他的敢為的乎？見他的可說的無證，見他的不可惡的無形，賞賜與刑罰不信於所見，而且求所不見的外，不可得啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「管子曰：「見其可說之有證，見其不可惡之有形，賞罰信於所見，雖所不見，其敢為之乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「管」、「子」、「見」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「管子曰見其可說之有證見其不可惡之有形賞罰信於所見」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「見其可說之無證，見其不可惡之無形，賞罰不信於所見，而求所不見之外，不可得也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-14\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 14,\n      \"canonicalText\": \"或曰：廣廷嚴居，眾人之所肅也；晏室獨處，曾、史之所僈也。觀人之所肅，非行、情也。且君上者，臣下之所為飾也。好惡在所見，臣下之飾姦物以愚其君，必也。明不能燭遠姦，見隱微，而待之以觀飾行，定賞罰，不亦弊乎！\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-14_s-1\",\n        \"han-fei-zi_ch-20_p-14_s-2\",\n        \"han-fei-zi_ch-20_p-14_s-3\",\n        \"han-fei-zi_ch-20_p-14_s-4\",\n        \"han-fei-zi_ch-20_p-14_s-5\",\n        \"han-fei-zi_ch-20_p-14_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：廣廷嚴居，眾人的所肅啊；晏室獨處，曾、史的所僈啊。觀人的所肅，絕不是行、情啊。且國君上的人或事，臣屬下的所為飾啊。好惡在所見，臣屬下的飾姦物以愚他的國君，必啊。明不能燭遠姦，見隱微，而且待的以觀飾行，定賞賜與刑罰，不亦弊乎！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：廣廷嚴居，眾人之所肅也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「廣」、「廷」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰廣廷嚴居眾人之所肅也晏室獨處曾史之所僈也觀人」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「晏室獨處，曾、史之所僈也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-15\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 15,\n      \"canonicalText\": \"管子曰：「言於室滿於室，言於堂滿於堂，是謂天下王。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-15_s-1\",\n        \"han-fei-zi_ch-20_p-15_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"管子說道：言於室滿於室，言於堂滿於堂，是謂天下王。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「管子曰：「言於室滿於室，言於堂滿於堂，是謂天下王」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「管」、「子」、「言」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「管子曰言於室滿於室言於堂滿於堂是謂天下王」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「管子曰：「言於室滿於室，言於堂滿於堂，是謂天下王」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-16\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"order\": 16,\n      \"canonicalText\": \"或曰：管仲之所謂言室滿室、言堂滿堂者，非特謂遊戲飲食之言也，必謂大物也。人主之大物，非法則術也。法者，編著之圖籍，設之於官府，而布之於百姓者也。術者，藏之於胸中，以偶眾端而潛御群臣者也。故法莫如顯，而術不欲見。是以明主言法，則境內卑賤莫不聞知也，不獨滿於堂。用術，則親愛近習莫之得聞也，不得滿室。而管子猶曰「言於室滿室，言於堂滿堂」，非法術之言也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-20_p-16_s-1\",\n        \"han-fei-zi_ch-20_p-16_s-2\",\n        \"han-fei-zi_ch-20_p-16_s-3\",\n        \"han-fei-zi_ch-20_p-16_s-4\",\n        \"han-fei-zi_ch-20_p-16_s-5\",\n        \"han-fei-zi_ch-20_p-16_s-6\",\n        \"han-fei-zi_ch-20_p-16_s-7\",\n        \"han-fei-zi_ch-20_p-16_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：管仲的所謂言室滿室、言堂滿堂的人或事，絕不是特謂遊戲飲食的言啊，必謂大物啊。人主的大物，絕不是法規法令則督察權術啊。法規法令的人或事，編著的圖籍，設的於官府，而且布的於百姓的人或事啊。督察權術的人或事，藏的於胸中，以偶眾端而且潛御群臣屬的人或事啊。所以法規法令莫如顯，而且督察權術不欲見。是以明主言法規法令，則境內卑賤莫不聞知啊，不獨滿於堂。用督察權術，則親愛近習莫的得聞啊，不得滿室。而且管子猶說道：言於室滿室，言於堂滿堂，絕不是法規法令督察權術的言啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難三〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：管仲之所謂言室滿室、言堂滿堂者，非特謂遊戲飲食之言也，必謂大物也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「管」、「仲」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰管仲之所謂言室滿室言堂滿堂者非特謂遊戲飲食之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「人主之大物，非法則術也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-20_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"魯穆公問於子思曰：「吾聞龐𥼴氏之子不孝，其行奚如？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"」子思對曰：「君子尊賢以崇德，舉善以觀民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"若夫過行，是細人之所識也，臣不知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"」子思出，子服厲伯入見，問龐𥼴氏子，子服厲伯對曰：「其過三，皆君之所未嘗聞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-1_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"」自是之後，君貴子思而賤子服厲伯也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：魯之公室，三世劫於季氏，不亦宜乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"明君求善而賞之，求姦而誅之，其得之一也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"故以善聞之者，以說善同於上者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"以姦聞之者，以惡姦同於上者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"此宜賞譽之所力也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-2_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"不以姦聞，是異於上而下比周於姦者也，此宜毀罰之所及也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-2_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"今子思不以過聞，而穆公貴之，厲伯以姦聞而穆公賤之，人情皆喜貴而惡賤，故季氏之亂成而不上聞，此魯君之所以劫也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-2_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"且此亡王之俗，取、魯之民所以自美，而穆公獨貴之，不亦倒乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"文公出亡，獻公使寺人披攻之蒲城，披斬其袪，文公奔翟。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"惠公即位，又使攻之惠竇，不得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"及文公反國，披求見。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"公曰：「蒲城之役，君令一宿，而汝即至；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"惠竇之難，君令三宿，而汝一宿，何其速也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"」披對曰：「君令不二，除君之惡，惟恐不堪，蒲人、翟人餘何有焉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"今公即位，其無蒲、翟乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"且桓公置射鉤而相管仲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-3_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"」君乃見之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：齊、晉絕祀，不亦宜乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"桓公能用管仲之功而忘射鉤之怨，文公能聽寺人之言而棄斬袪之罪，桓公、文公能容二子者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"後世之君，明不及二公；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"後世之臣，賢不如二子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"以不忠之臣事不明之君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"君不知，則有燕操、子罕、田常之賊；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"知之，則以管仲、寺人自解。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"君必不誅，而自以為有桓、文之德，是臣讎而明不能燭，多假之資。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"自以為賢而不戒，則雖無後嗣，不亦可乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"且寺人之言也，直飾君令而不貳者，則是貞於君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-4_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"死君後生臣不愧而復為貞，今惠公朝卒而暮事文公，寺人之不貳何如？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"人有設桓公隱者曰：「一難，二難，三難，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"」桓公不能對，以告管仲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"管仲對曰：「一難也、近優而遠士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"二難也、去其國而數之海。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"三難也、君老而晚置太子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"」桓公曰：「善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-5_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"」不擇日而廟禮太子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：管仲之射隱不得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"士之用不在近遠。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"而俳優侏儒，固人主之所與燕也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"則近優而遠士，而以為治，非其難者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"夫處勢而不能用其有，而悖不去國，是以一人之力禁一國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"以一人之力禁一國者，少能勝之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"明能照遠姦而見隱微，必行之令，雖遠於海，內必無變；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"然則去國之海而不劫殺，非其難者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"楚成王置商臣以為太子，又欲置公子職，商臣作難，遂弒成王。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"公子宰，周太子也，公子根有寵，遂以東州反，分而為兩國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"此皆非晚置太子之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"夫分勢不二，庶孽卑，寵無藉，雖處大臣，晚置太子可也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 13,\n      \"canonicalText\": \"然則晚置太子，庶孽不亂，又非其難也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 14,\n      \"canonicalText\": \"物之所謂難者；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 15,\n      \"canonicalText\": \"必借人成勢而勿使侵害己，可謂一難也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 16,\n      \"canonicalText\": \"貴妾不使二後，二難也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-6_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-6\",\n      \"order\": 17,\n      \"canonicalText\": \"愛孽不使危正適，專聽一臣而不敢隅君，此則可謂三難也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"葉公子高問政於仲尼，仲尼曰：「政在悅近而來遠。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-7_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"」哀公問政於仲尼，仲尼曰：「政在選賢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-7_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"」齊景公問政於仲尼，仲尼曰：「政在節財。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-7_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"」三公出，子貢問曰：「三公問夫子政一也，夫子對之不同，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-7_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"」仲尼曰：「葉都大而國小，民有背心，故曰政在悅近而來遠。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-7_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"魯哀公有大臣三人，外障距諸侯四鄰之士，內比周而以愚其君，使宗廟不掃除，社稷不血食者，必是三臣也，故曰政在選賢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-7_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"齊景公築雍門，為路寢，一朝而以三百乘之家賜者三，故曰政在節財。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-7_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：仲尼之對，亡國之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"葉民有倍心，而說之悅近而來遠，則是教民懷惠。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"惠之為政，無功者受賞，而有罪者免，此法之所以敗也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"法敗而政亂，以亂政治敗民，未見其可也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"且民有倍心者，君上之明有所不及也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"不紹葉公之明，而使之悅近而來遠，是舍吾勢之所能禁而使與不行惠以爭民，非能持勢者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"夫堯之賢，六王之冠也，舜一從而鹹包，而堯無天下矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"有人無術以禁下，恃為舜而不失其民，不亦無術乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"明君見小姦於微，故民無大謀；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"行小誅於細，故民無大亂；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 11,\n      \"canonicalText\": \"此謂圖難於其所易也，為大者於其所細也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 12,\n      \"canonicalText\": \"今有功者必賞，賞者不得君，力之所致也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 13,\n      \"canonicalText\": \"有罪者必誅，誅者不怨上，罪之所生也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 14,\n      \"canonicalText\": \"民知誅罰之皆起於身也，故疾功利於業，而不受賜於君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 15,\n      \"canonicalText\": \"「太上、下智有之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 16,\n      \"canonicalText\": \"」此言太上之下民無說也，安取懷惠之民？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 17,\n      \"canonicalText\": \"上君之民無利害，說以悅近來遠，亦可捨己。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 18,\n      \"canonicalText\": \"哀公有臣外障距內比周以愚其君，而說之以選賢，此非功伐之論也，選其心之所謂賢者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 19,\n      \"canonicalText\": \"使哀公知三子外障距內比周也，則三子不一日立矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 20,\n      \"canonicalText\": \"哀公不知選賢，選其心之所謂賢，故三子得任事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 21,\n      \"canonicalText\": \"燕子噲賢子之而非孫卿，故身死為僇。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 22,\n      \"canonicalText\": \"夫差智太宰嚭而愚子胥，故滅於越。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-23\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 23,\n      \"canonicalText\": \"魯君不必知賢，而說以選賢，是使哀公有夫差、燕噲之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-24\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 24,\n      \"canonicalText\": \"明君不自舉臣，臣相進也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-25\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 25,\n      \"canonicalText\": \"不自賢，功自徇也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-26\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 26,\n      \"canonicalText\": \"論之於任，試之於事，課之於功。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-27\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 27,\n      \"canonicalText\": \"故群臣公政而無私，不隱賢，不進不肖，然則人主奚勞於選賢？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-28\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 28,\n      \"canonicalText\": \"景公以百乘之家賜，而說以節財，是使景公無術使智君之侈，而獨儉於上，未免於貧也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-29\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 29,\n      \"canonicalText\": \"有君以千里養其口腹，則雖桀、紂不侈焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-30\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 30,\n      \"canonicalText\": \"齊國方三千里，而桓公以其半自養，是侈於桀、紂也，然而能為五霸冠者，知侈儉之地也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-31\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 31,\n      \"canonicalText\": \"為君不能禁下而自禁者謂之劫，不能飾下而自飾者謂之亂，不節下而自節者謂之貧。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-32\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 32,\n      \"canonicalText\": \"明君使人無私，以詐而食者禁；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-33\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 33,\n      \"canonicalText\": \"力盡於事，歸利於上者必聞，聞者必賞；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-34\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 34,\n      \"canonicalText\": \"污穢為私者必知，知者必誅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-35\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 35,\n      \"canonicalText\": \"然故忠臣盡忠於方公，民士竭力於家，百官精剋於上，侈倍景公，非國之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-36\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 36,\n      \"canonicalText\": \"然則說之以節財，非其急者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-37\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 37,\n      \"canonicalText\": \"夫對三公一言而三公可以無患，知下之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-38\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 38,\n      \"canonicalText\": \"知下明則禁於微，禁於微則姦無積，姦無積則無比周。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-39\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 39,\n      \"canonicalText\": \"無比周則公私分，公私分則朋黨散，朋黨散則無外障距內比周之患。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-8_s-40\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-8\",\n      \"order\": 40,\n      \"canonicalText\": \"知下明則見精沐，見精沐則誅賞明，誅賞明則國不貧，故曰一對而三公無患，知下之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"鄭子產晨出，過東匠之閭，聞婦人之哭，撫其御之手而聽之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"有閒，遣吏執而問之，則手絞其夫者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"異日，其御問曰：「夫子何以知之？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-9_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"」子產曰：「其聲懼。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-9_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"凡人於其親愛也，始病而憂，臨死而懼，已死而哀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-9_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"今哭已死不哀而懼，是以知其有姦也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-9_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：子產之治，不亦多事乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"姦必待耳目之所及而後知之，則鄭國之得姦者寡矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"不任典成之吏，不察參伍之政，不明度量，恃盡聰明，勞智慮，而以知姦，不亦無術乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"且夫物眾而智寡，寡不勝眾，智不足以遍知物，故因物以治物。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"下眾而上寡，寡不勝眾，者言君不足以遍知臣也，故因人以知人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"是以形體不勞而事治，智慮不用而姦得。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"故宋人語曰：「一雀過羿，羿必得之，則羿誣矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"以天下為之羅，則雀不失矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"」夫知姦亦有大羅，不失其一而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"不修其理，而以己之胸察為之弓矢，則子產誣矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 11,\n      \"canonicalText\": \"老子曰：「以智治國，國之賊也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-10_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-10\",\n      \"order\": 12,\n      \"canonicalText\": \"」其子產之謂矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"秦昭王問於左右曰：「今時韓、魏孰與始強？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"」左右對曰：「弱於始也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"」「今之如耳、魏齊孰與曩之孟常、芒卯？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"」對曰：「不及也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"」王曰：「孟常、芒卯率強韓、魏猶無奈寡人何也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"」左右對曰：「甚然！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 7,\n      \"canonicalText\": \"」中期推琴而對曰：「王之料天下過矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 8,\n      \"canonicalText\": \"夫六晉之時，知氏最強，滅範、中行而從韓、魏之兵以伐趙，灌以晉水，城之未沈者三板。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 9,\n      \"canonicalText\": \"知伯出，魏宣子御，韓康子為驂乘，知伯曰：「始吾不知水可以滅人之國，吾乃今知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 10,\n      \"canonicalText\": \"汾水可以灌安邑，絳水可以灌平陽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 11,\n      \"canonicalText\": \"」魏宣子肘韓康子，康子踐宣子之足，肘足接乎車上，而知氏分於晉陽之下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 12,\n      \"canonicalText\": \"今足下雖強，未若知氏；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 13,\n      \"canonicalText\": \"韓、魏雖弱，未至如其在晉陽之下也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 14,\n      \"canonicalText\": \"此天下方用肘足之時，願王勿易之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-11_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-11\",\n      \"order\": 15,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：昭王之問也有失，左右中期之對也有過。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"凡明主之治國也，任其勢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"勢不可害，則雖強天下無奈何也，而況孟常、芒卯、韓、魏能奈我何！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"其勢可害也，則不肖如如耳、魏齊，及韓、魏猶能害之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"然則害與不侵，在自恃而已矣，奚問乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"自恃其不可侵，則強與弱奚其擇焉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"失在不自恃，而問其奈何也，其不侵也幸矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"《申子》曰：「失之數而求之信則疑矣，」其昭王之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 9,\n      \"canonicalText\": \"知伯無度，從韓康、魏宣而圖以水灌滅其國，此知伯之所以國亡而身死、頭為飲杯之故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 10,\n      \"canonicalText\": \"今昭王乃問孰與始強，其畏有水人之患乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 11,\n      \"canonicalText\": \"雖有左右非韓、魏之二子也，安有肘足之事，而中期曰「勿易」，此虛言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 12,\n      \"canonicalText\": \"且中期之所官、琴瑟也，絃不調，弄不明，中期之任也，此中期所以事昭王者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 13,\n      \"canonicalText\": \"中期善承其任，未慊昭王也，而為所不知，豈不妄哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 14,\n      \"canonicalText\": \"左右對之曰「弱於始」與「不及」則可矣，其曰「甚然」則諛也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 15,\n      \"canonicalText\": \"《申子》曰：「治不踰官，雖知不言。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 16,\n      \"canonicalText\": \"」今中期不知而尚言之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-12_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-12\",\n      \"order\": 17,\n      \"canonicalText\": \"故曰昭王之問有失，左右中期之對皆有過也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-13_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"管子曰：「見其可說之有證，見其不可惡之有形，賞罰信於所見，雖所不見，其敢為之乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-13_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"見其可說之無證，見其不可惡之無形，賞罰不信於所見，而求所不見之外，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-13_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-14_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：廣廷嚴居，眾人之所肅也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-14_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"晏室獨處，曾、史之所僈也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-14_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"觀人之所肅，非行、情也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-14_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"且君上者，臣下之所為飾也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-14_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-14\",\n      \"order\": 5,\n      \"canonicalText\": \"好惡在所見，臣下之飾姦物以愚其君，必也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-14_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-14\",\n      \"order\": 6,\n      \"canonicalText\": \"明不能燭遠姦，見隱微，而待之以觀飾行，定賞罰，不亦弊乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-15_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"管子曰：「言於室滿於室，言於堂滿於堂，是謂天下王。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-15_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-16_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：管仲之所謂言室滿室、言堂滿堂者，非特謂遊戲飲食之言也，必謂大物也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-16_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"人主之大物，非法則術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-16_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"法者，編著之圖籍，設之於官府，而布之於百姓者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-16_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"術者，藏之於胸中，以偶眾端而潛御群臣者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-16_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-16\",\n      \"order\": 5,\n      \"canonicalText\": \"故法莫如顯，而術不欲見。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-16_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-16\",\n      \"order\": 6,\n      \"canonicalText\": \"是以明主言法，則境內卑賤莫不聞知也，不獨滿於堂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-16_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-16\",\n      \"order\": 7,\n      \"canonicalText\": \"用術，則親愛近習莫之得聞也，不得滿室。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-20_p-16_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-20\",\n      \"passageId\": \"han-fei-zi_ch-20_p-16\",\n      \"order\": 8,\n      \"canonicalText\": \"而管子猶曰「言於室滿室，言於堂滿堂」，非法術之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
